import type { Dialogue, DialogueLine } from './dialogues';

type Turn = { speaker: 0 | 1; text: string; translation: string };
type DialogueSeed = {
  id: number; level: 'A1' | 'A2' | 'B1' | 'B2' | 'C1'; title: string; titleEs: string;
  summaryEs: string; names: [string, string]; roles: [string, string]; turns: Turn[];
};

const seeds: DialogueSeed[] = [
  { id:3, level:'A1', title:'A Friendly Greeting', titleEs:'Un saludo amable', summaryEs:'Dos vecinos se conocen en la cafetería del edificio.', names:['Ana (Neighbor)','Ben (Neighbor)'], roles:['student','neighbor'], turns:[
    {speaker:0,text:'Good morning. Is this seat free?',translation:'Buenos días. ¿Está libre este asiento?'},{speaker:1,text:'Yes, it is. Please sit down.',translation:'Sí, lo está. Por favor, siéntate.'},{speaker:0,text:'Thank you. My name is Ana. I live upstairs.',translation:'Gracias. Me llamo Ana. Vivo arriba.'},{speaker:1,text:'Nice to meet you, Ana. I am Ben. I live next door.',translation:'Mucho gusto, Ana. Soy Ben. Vivo al lado.'},{speaker:0,text:'Nice to meet you too. Do you come here every morning?',translation:'Mucho gusto también. ¿Vienes aquí todas las mañanas?'},{speaker:1,text:'Yes. I have coffee before work.',translation:'Sí. Tomo café antes del trabajo.'}] },
  { id:4, level:'A1', title:'In the English Class', titleEs:'En la clase de inglés', summaryEs:'Una estudiante nueva se presenta a su grupo.', names:['Mia (Student)','Mr. Green (Teacher)'], roles:['student','teacher'], turns:[
    {speaker:0,text:'Hello. I am Mia. I am new in this class.',translation:'Hola. Soy Mia. Soy nueva en esta clase.'},{speaker:1,text:'Welcome, Mia. Where are you from?',translation:'Bienvenida, Mia. ¿De dónde eres?'},{speaker:0,text:'I am from Mexico. I live near the school.',translation:'Soy de México. Vivo cerca de la escuela.'},{speaker:1,text:'That is great. Do you speak English?',translation:'Qué bien. ¿Hablas inglés?'},{speaker:0,text:'A little. I practice every day.',translation:'Un poco. Practico todos los días.'},{speaker:1,text:'Excellent. Please sit next to Carlos.',translation:'Excelente. Por favor, siéntate junto a Carlos.'}] },
  { id:5, level:'A1', title:'Breakfast at the Café', titleEs:'Desayuno en la cafetería', summaryEs:'Una clienta pide un desayuno sencillo.', names:['Ella (Customer)','Jack (Server)'], roles:['customer','server'], turns:[
    {speaker:0,text:'Good morning. Can I have a menu, please?',translation:'Buenos días. ¿Me da un menú, por favor?'},{speaker:1,text:'Of course. Here you are.',translation:'Claro. Aquí tiene.'},{speaker:0,text:'I would like eggs and toast, please.',translation:'Quisiera huevos y pan tostado, por favor.'},{speaker:1,text:'Would you like tea or coffee?',translation:'¿Quiere té o café?'},{speaker:0,text:'Tea, please. No sugar.',translation:'Té, por favor. Sin azúcar.'},{speaker:1,text:'Certainly. Your breakfast will be ready soon.',translation:'Por supuesto. Su desayuno estará listo pronto.'}] },
  { id:6, level:'A1', title:'Finding the Bus Stop', titleEs:'Cómo encontrar la parada', summaryEs:'Un visitante pregunta dónde tomar el autobús.', names:['Leo (Visitor)','Nora (Local Resident)'], roles:['customer','neighbor'], turns:[
    {speaker:0,text:'Excuse me. Where is the bus stop?',translation:'Disculpe. ¿Dónde está la parada de autobús?'},{speaker:1,text:'It is next to the bank.',translation:'Está junto al banco.'},{speaker:0,text:'Is it far from here?',translation:'¿Está lejos de aquí?'},{speaker:1,text:'No. Go straight for two minutes.',translation:'No. Sigue derecho durante dos minutos.'},{speaker:0,text:'Do I turn left at the shop?',translation:'¿Giro a la izquierda en la tienda?'},{speaker:1,text:'Yes. The stop is on your left.',translation:'Sí. La parada está a tu izquierda.'}] },
  { id:7, level:'A1', title:'Buying a Blue Shirt', titleEs:'Comprar una camisa azul', summaryEs:'Un cliente busca una camisa de su talla.', names:['Tom (Customer)','Sara (Shop Assistant)'], roles:['customer','assistant'], turns:[
    {speaker:0,text:'Hello. I need a blue shirt.',translation:'Hola. Necesito una camisa azul.'},{speaker:1,text:'What size do you wear?',translation:'¿Qué talla usas?'},{speaker:0,text:'I wear a medium. How much is this one?',translation:'Uso mediana. ¿Cuánto cuesta esta?'},{speaker:1,text:'It is twenty dollars.',translation:'Cuesta veinte dólares.'},{speaker:0,text:'Can I try it on?',translation:'¿Me la puedo probar?'},{speaker:1,text:'Yes. The fitting room is over there.',translation:'Sí. El probador está allá.'}] },
  { id:8, level:'A1', title:'At the Library', titleEs:'En la biblioteca', summaryEs:'Una lectora pide un libro para practicar inglés.', names:['Eva (Reader)','Mr. Lee (Librarian)'], roles:['student','librarian'], turns:[
    {speaker:0,text:'Hello. I want an easy book in English.',translation:'Hola. Quiero un libro fácil en inglés.'},{speaker:1,text:'What do you like to read?',translation:'¿Qué te gusta leer?'},{speaker:0,text:'I like stories about animals.',translation:'Me gustan las historias de animales.'},{speaker:1,text:'This book is short and has pictures.',translation:'Este libro es corto y tiene ilustraciones.'},{speaker:0,text:'Great. Can I borrow it today?',translation:'Genial. ¿Lo puedo llevar prestado hoy?'},{speaker:1,text:'Yes. Please bring it back next Friday.',translation:'Sí. Por favor, devuélvelo el próximo viernes.'}] },
  { id:9, level:'A1', title:'Weekend Plans', titleEs:'Planes para el fin de semana', summaryEs:'Dos amigos hablan de sus actividades del sábado.', names:['Lily (Friend)','Mark (Friend)'], roles:['student','friend'], turns:[
    {speaker:0,text:'What do you do on Saturdays?',translation:'¿Qué haces los sábados?'},{speaker:1,text:'I usually play football in the park.',translation:'Normalmente juego fútbol en el parque.'},{speaker:0,text:'I visit my grandmother. She lives nearby.',translation:'Visito a mi abuela. Vive cerca.'},{speaker:1,text:'Does she cook lunch for you?',translation:'¿Ella te prepara el almuerzo?'},{speaker:0,text:'Yes. We eat together at one o’clock.',translation:'Sí. Comemos juntos a la una.'},{speaker:1,text:'That sounds lovely. Have a nice weekend!',translation:'Suena muy bien. ¡Que tengas un buen fin de semana!'}] },
  { id:10, level:'A1', title:'Family Photo', titleEs:'Una foto familiar', summaryEs:'Una estudiante describe a su familia con una fotografía.', names:['Anna (Student)','Paul (Classmate)'], roles:['student','classmate'], turns:[
    {speaker:0,text:'This is a photo of my family.',translation:'Esta es una foto de mi familia.'},{speaker:1,text:'Who is the woman in the middle?',translation:'¿Quién es la mujer en el centro?'},{speaker:0,text:'That is my mother. She is a doctor.',translation:'Esa es mi madre. Es doctora.'},{speaker:1,text:'And who is the boy beside her?',translation:'¿Y quién es el chico junto a ella?'},{speaker:0,text:'He is my little brother. His name is Luis.',translation:'Es mi hermano menor. Se llama Luis.'},{speaker:1,text:'Your family looks very happy.',translation:'Tu familia se ve muy feliz.'}] },
  { id:11, level:'A1', title:'A Visit to the Doctor', titleEs:'Una visita al médico', summaryEs:'Una paciente explica un malestar sencillo.', names:['Nina (Patient)','Dr. Hill (Doctor)'], roles:['customer','doctor'], turns:[
    {speaker:0,text:'Good morning, Doctor. I have a headache.',translation:'Buenos días, doctor. Me duele la cabeza.'},{speaker:1,text:'When did it start?',translation:'¿Cuándo empezó?'},{speaker:0,text:'It started last night. I feel tired too.',translation:'Empezó anoche. También me siento cansada.'},{speaker:1,text:'Do you have a fever?',translation:'¿Tienes fiebre?'},{speaker:0,text:'No, I do not. I have a little cough.',translation:'No. Tengo un poco de tos.'},{speaker:1,text:'Please drink water and rest today.',translation:'Por favor, toma agua y descansa hoy.'}] },
  { id:12, level:'A1', title:'A Bus Ticket', titleEs:'Un boleto de autobús', summaryEs:'Un pasajero compra un boleto para el centro.', names:['Sam (Passenger)','Iris (Ticket Clerk)'], roles:['customer','assistant'], turns:[
    {speaker:0,text:'One ticket to the city center, please.',translation:'Un boleto al centro, por favor.'},{speaker:1,text:'Single or return?',translation:'¿Sencillo o redondo?'},{speaker:0,text:'Single, please. How much is it?',translation:'Sencillo, por favor. ¿Cuánto cuesta?'},{speaker:1,text:'It is three dollars.',translation:'Cuesta tres dólares.'},{speaker:0,text:'Here is five dollars.',translation:'Aquí tiene cinco dólares.'},{speaker:1,text:'Thank you. Here is your ticket and change.',translation:'Gracias. Aquí tiene su boleto y su cambio.'}] },

  { id:13, level:'A2', title:'Changing a Hotel Booking', titleEs:'Cambiar una reservación de hotel', summaryEs:'Una viajera solicita cambiar la fecha de su estancia.', names:['Marta (Guest)','Oliver (Receptionist)'], roles:['customer','assistant'], turns:[
    {speaker:0,text:'I have a room booked for Friday, but I need to arrive on Saturday.',translation:'Tengo una habitación reservada para el viernes, pero necesito llegar el sábado.'},{speaker:1,text:'I can check that for you. What name is the booking under?',translation:'Puedo revisarlo. ¿A nombre de quién está la reserva?'},{speaker:0,text:'It is under Marta Ruiz. I will stay for two nights.',translation:'Está a nombre de Marta Ruiz. Me quedaré dos noches.'},{speaker:1,text:'We have a room available on Saturday. The price is the same.',translation:'Tenemos una habitación disponible el sábado. El precio es el mismo.'},{speaker:0,text:'That works for me. Could you send me the new confirmation?',translation:'Me parece bien. ¿Podría enviarme la nueva confirmación?'},{speaker:1,text:'Certainly. I have sent it to your email address.',translation:'Por supuesto. La envié a su correo electrónico.'}] },
  { id:14, level:'A2', title:'Returning a Jacket', titleEs:'Devolver una chamarra', summaryEs:'Un cliente cambia una prenda que no le quedó bien.', names:['Diego (Customer)','Fiona (Shop Assistant)'], roles:['customer','assistant'], turns:[
    {speaker:0,text:'I bought this jacket yesterday, but it is too small.',translation:'Compré esta chamarra ayer, pero me queda muy pequeña.'},{speaker:1,text:'Do you have the receipt with you?',translation:'¿Trae el recibo?'},{speaker:0,text:'Yes, here it is. Do you have the next size?',translation:'Sí, aquí está. ¿Tiene la talla siguiente?'},{speaker:1,text:'Let me check. We have a large in the same color.',translation:'Déjeme revisar. Tenemos una grande del mismo color.'},{speaker:0,text:'May I try it on before I exchange it?',translation:'¿Me la puedo probar antes de cambiarla?'},{speaker:1,text:'Of course. The fitting rooms are at the back.',translation:'Claro. Los probadores están al fondo.'}] },
  { id:15, level:'A2', title:'Planning a Day Trip', titleEs:'Planear una excursión de un día', summaryEs:'Dos amigos organizan una visita a un pueblo cercano.', names:['Rosa (Friend)','Ethan (Friend)'], roles:['student','friend'], turns:[
    {speaker:0,text:'Would you like to visit the old town on Sunday?',translation:'¿Te gustaría visitar el pueblo antiguo el domingo?'},{speaker:1,text:'Yes. How can we get there?',translation:'Sí. ¿Cómo podemos llegar?'},{speaker:0,text:'A train leaves at nine, and the journey takes an hour.',translation:'Sale un tren a las nueve y el viaje dura una hora.'},{speaker:1,text:'Let us take the early train so we have more time.',translation:'Tomemos el tren temprano para tener más tiempo.'},{speaker:0,text:'Good idea. I will buy the tickets online tonight.',translation:'Buena idea. Compraré los boletos por internet esta noche.'},{speaker:1,text:'I will bring lunch and a map.',translation:'Yo llevaré el almuerzo y un mapa.'}] },
  { id:16, level:'A2', title:'A Noisy Apartment', titleEs:'Un departamento ruidoso', summaryEs:'Una inquilina conversa con el encargado sobre un ruido.', names:['Clara (Tenant)','Mr. Brown (Building Manager)'], roles:['customer','manager'], turns:[
    {speaker:0,text:'I am sorry to bother you, but there is a loud noise in my apartment.',translation:'Disculpe la molestia, pero hay un ruido fuerte en mi departamento.'},{speaker:1,text:'When do you usually hear it?',translation:'¿Cuándo suele escucharlo?'},{speaker:0,text:'It starts around ten every night and comes from the kitchen.',translation:'Empieza alrededor de las diez cada noche y viene de la cocina.'},{speaker:1,text:'I will ask the maintenance team to inspect the refrigerator tomorrow.',translation:'Mañana pediré al equipo de mantenimiento que revise el refrigerador.'},{speaker:0,text:'Thank you. I will be home after five.',translation:'Gracias. Estaré en casa después de las cinco.'},{speaker:1,text:'I will let them know. We will contact you before they arrive.',translation:'Se lo haré saber. Nos pondremos en contacto antes de que lleguen.'}] },
  { id:17, level:'A2', title:'At the Pharmacy', titleEs:'En la farmacia', summaryEs:'Una persona pregunta por un medicamento para la tos.', names:['Pablo (Customer)','June (Pharmacist)'], roles:['customer','pharmacist'], turns:[
    {speaker:0,text:'I have had a cough for three days. Can you recommend something?',translation:'Tengo tos desde hace tres días. ¿Puede recomendarme algo?'},{speaker:1,text:'Do you have a fever or any allergies?',translation:'¿Tiene fiebre o alguna alergia?'},{speaker:0,text:'I do not have a fever, but I am allergic to aspirin.',translation:'No tengo fiebre, pero soy alérgico a la aspirina.'},{speaker:1,text:'This syrup does not contain aspirin. Please follow the instructions on the label.',translation:'Este jarabe no contiene aspirina. Siga las instrucciones de la etiqueta.'},{speaker:0,text:'How often should I take it?',translation:'¿Cada cuánto debo tomarlo?'},{speaker:1,text:'The label says twice a day. Ask a doctor if you feel worse.',translation:'La etiqueta dice dos veces al día. Consulte a un médico si empeora.'}] },
  { id:18, level:'A2', title:'A Delayed Train', titleEs:'Un tren retrasado', summaryEs:'Una pasajera busca una alternativa por un retraso.', names:['Sofia (Passenger)','Alex (Station Agent)'], roles:['customer','assistant'], turns:[
    {speaker:0,text:'The screen says my train is delayed by forty minutes. Is that correct?',translation:'La pantalla dice que mi tren tiene cuarenta minutos de retraso. ¿Es correcto?'},{speaker:1,text:'Yes. There is a signal problem on the line.',translation:'Sí. Hay un problema de señalización en la vía.'},{speaker:0,text:'I need to reach the airport before noon. Is there another route?',translation:'Necesito llegar al aeropuerto antes del mediodía. ¿Hay otra ruta?'},{speaker:1,text:'You can take the next train to Central Station and change there.',translation:'Puede tomar el siguiente tren a la Estación Central y cambiar allí.'},{speaker:0,text:'Will my ticket work on that train?',translation:'¿Mi boleto sirve para ese tren?'},{speaker:1,text:'Yes, it will. Follow the blue signs to platform four.',translation:'Sí. Siga las señales azules hasta el andén cuatro.'}] },
  { id:19, level:'A2', title:'Making a Doctor’s Appointment', titleEs:'Pedir una cita médica', summaryEs:'Un paciente agenda una consulta para la próxima semana.', names:['Luis (Patient)','Nora (Receptionist)'], roles:['customer','assistant'], turns:[
    {speaker:0,text:'I would like to make an appointment with Dr. Green.',translation:'Quisiera hacer una cita con la doctora Green.'},{speaker:1,text:'Is this your first visit to our clinic?',translation:'¿Es su primera visita a nuestra clínica?'},{speaker:0,text:'No, I visited last year. I have had back pain since Monday.',translation:'No, vine el año pasado. Tengo dolor de espalda desde el lunes.'},{speaker:1,text:'She is available on Tuesday at eleven or Wednesday at three.',translation:'Tiene espacio el martes a las once o el miércoles a las tres.'},{speaker:0,text:'Tuesday at eleven is better. Should I bring anything?',translation:'El martes a las once está mejor. ¿Debo llevar algo?'},{speaker:1,text:'Please bring your insurance card and arrive ten minutes early.',translation:'Traiga su tarjeta del seguro y llegue diez minutos antes.'}] },
  { id:20, level:'A2', title:'Choosing a Weekend Activity', titleEs:'Elegir una actividad de fin de semana', summaryEs:'Dos compañeros deciden qué hacer si llueve.', names:['Maya (Friend)','Noah (Friend)'], roles:['student','friend'], turns:[
    {speaker:0,text:'The weather may be rainy on Saturday. What should we do?',translation:'Puede llover el sábado. ¿Qué deberíamos hacer?'},{speaker:1,text:'We could visit the science museum. It is indoors.',translation:'Podríamos visitar el museo de ciencias. Es bajo techo.'},{speaker:0,text:'That sounds interesting. Have you been there before?',translation:'Suena interesante. ¿Has ido antes?'},{speaker:1,text:'Yes, I went last year, and the new space exhibit opens this week.',translation:'Sí, fui el año pasado y la nueva exposición espacial abre esta semana.'},{speaker:0,text:'If it rains, let us go there after lunch.',translation:'Si llueve, vayamos después del almuerzo.'},{speaker:1,text:'Great. I will check the opening hours tonight.',translation:'Perfecto. Revisaré el horario esta noche.'}] },
  { id:21, level:'A2', title:'A Lost Phone', titleEs:'Un teléfono perdido', summaryEs:'Un pasajero pregunta en objetos perdidos por su celular.', names:['Nadia (Passenger)','Mr. Cole (Staff Member)'], roles:['customer','assistant'], turns:[
    {speaker:0,text:'I think I left my phone on the number twelve bus.',translation:'Creo que dejé mi teléfono en el autobús número doce.'},{speaker:1,text:'What time did you get off?',translation:'¿A qué hora se bajó?'},{speaker:0,text:'At about six. It is black, and it has a red case.',translation:'Como a las seis. Es negro y tiene una funda roja.'},{speaker:1,text:'A driver brought in a phone that matches that description.',translation:'Un conductor trajo un teléfono que coincide con esa descripción.'},{speaker:0,text:'That may be mine. Can I check it?',translation:'Podría ser el mío. ¿Puedo revisarlo?'},{speaker:1,text:'Certainly. Please unlock it to confirm it belongs to you.',translation:'Por supuesto. Desbloquéelo para confirmar que es suyo.'}] },
  { id:22, level:'A2', title:'A New Neighbor', titleEs:'Una nueva vecina', summaryEs:'Dos vecinos acuerdan organizar una reunión para conocerse.', names:['Hana (New Neighbor)','Peter (Neighbor)'], roles:['student','neighbor'], turns:[
    {speaker:0,text:'Hello. I moved into apartment four yesterday.',translation:'Hola. Ayer me mudé al departamento cuatro.'},{speaker:1,text:'Welcome to the building. Do you need help carrying anything?',translation:'Bienvenida al edificio. ¿Necesitas ayuda con algo?'},{speaker:0,text:'Thank you. I have finished unpacking, but I do not know many people yet.',translation:'Gracias. Ya terminé de desempacar, pero todavía no conozco a muchas personas.'},{speaker:1,text:'We are having a small barbecue in the courtyard on Saturday.',translation:'Haremos una pequeña parrillada en el patio el sábado.'},{speaker:0,text:'That sounds nice. Should I bring something?',translation:'Qué agradable. ¿Debo llevar algo?'},{speaker:1,text:'Bring a drink if you like. We will provide the food.',translation:'Trae una bebida si quieres. Nosotros ponemos la comida.'}] },

  { id:23, level:'B1', title:'Preparing for a Job Interview', titleEs:'Prepararse para una entrevista de trabajo', summaryEs:'Una mentora ayuda a un candidato a preparar ejemplos claros.', names:['Chris (Applicant)','Maya (Mentor)'], roles:['student','teacher'], turns:[
    {speaker:0,text:'I have an interview tomorrow, and I am not sure how to answer questions about teamwork.',translation:'Mañana tengo una entrevista y no estoy seguro de cómo responder preguntas sobre trabajo en equipo.'},{speaker:1,text:'Choose one real example and explain your role, the challenge, and the result.',translation:'Elige un ejemplo real y explica tu papel, el desafío y el resultado.'},{speaker:0,text:'I helped my group finish a report when two members were absent.',translation:'Ayudé a mi grupo a terminar un informe cuando dos integrantes faltaron.'},{speaker:1,text:'Good. What did you do specifically?',translation:'Bien. ¿Qué hiciste específicamente?'},{speaker:0,text:'I divided the remaining tasks and checked that everyone had the same information.',translation:'Dividí las tareas restantes y verifiqué que todos tuvieran la misma información.'},{speaker:1,text:'That shows initiative. Keep the answer concise and give credit to the team.',translation:'Eso demuestra iniciativa. Mantén la respuesta concisa y reconoce el trabajo del equipo.'}] },
  { id:24, level:'B1', title:'Working Through a Group Project', titleEs:'Resolver un desacuerdo en un proyecto', summaryEs:'Compañeros reorganizan el trabajo tras un desacuerdo.', names:['Aisha (Student)','Ben (Student)'], roles:['student','classmate'], turns:[
    {speaker:0,text:'I am worried that our presentation has too many slides and not enough evidence.',translation:'Me preocupa que nuestra presentación tenga demasiadas diapositivas y poca evidencia.'},{speaker:1,text:'I made most of the slides, so I thought the structure was clear.',translation:'Hice la mayoría de las diapositivas, así que pensé que la estructura era clara.'},{speaker:0,text:'The structure is good. Perhaps we can remove repeated points and add two sources.',translation:'La estructura está bien. Tal vez podamos quitar ideas repetidas y añadir dos fuentes.'},{speaker:1,text:'That seems fair. Can you find the sources while I shorten the slides?',translation:'Me parece justo. ¿Puedes buscar las fuentes mientras yo acorto las diapositivas?'},{speaker:0,text:'Yes. Let us compare the new version this afternoon.',translation:'Sí. Comparemos la nueva versión esta tarde.'},{speaker:1,text:'Agreed. Thanks for explaining your concerns clearly.',translation:'De acuerdo. Gracias por explicar tus inquietudes con claridad.'}] },
  { id:25, level:'B1', title:'Reporting a Repair Problem', titleEs:'Informar un problema de mantenimiento', summaryEs:'Una inquilina y el encargado coordinan una reparación.', names:['Elena (Tenant)','Mr. Jones (Landlord)'], roles:['customer','manager'], turns:[
    {speaker:0,text:'The heater has stopped working twice this week, and the bedroom is getting cold.',translation:'El calentador dejó de funcionar dos veces esta semana y el dormitorio se está enfriando.'},{speaker:1,text:'I am sorry about that. Did you notice any warning light?',translation:'Lamento eso. ¿Notaste alguna luz de advertencia?'},{speaker:0,text:'A red light flashed before it stopped. I turned it off for safety.',translation:'Una luz roja parpadeó antes de que se detuviera. Lo apagué por seguridad.'},{speaker:1,text:'That was sensible. I will arrange for a technician to visit tomorrow morning.',translation:'Fue sensato. Coordinaré que un técnico venga mañana por la mañana.'},{speaker:0,text:'I will be home until noon. Could they call before arriving?',translation:'Estaré en casa hasta el mediodía. ¿Podrían llamar antes de llegar?'},{speaker:1,text:'Certainly. I will add that to the request and update you today.',translation:'Por supuesto. Lo añadiré a la solicitud y le avisaré hoy.'}] },
  { id:26, level:'B1', title:'Volunteering at the Food Bank', titleEs:'Ser voluntario en el banco de alimentos', summaryEs:'Una coordinadora explica tareas a un nuevo voluntario.', names:['Mateo (Volunteer)','Grace (Coordinator)'], roles:['student','coordinator'], turns:[
    {speaker:0,text:'I would like to volunteer on Saturdays. What kind of help do you need?',translation:'Me gustaría ser voluntario los sábados. ¿Qué tipo de ayuda necesitan?'},{speaker:1,text:'We sort donations, prepare food boxes, and welcome families.',translation:'Clasificamos donaciones, preparamos cajas de alimentos y recibimos a las familias.'},{speaker:0,text:'I have worked in a grocery store, so I can help check dates and organize shelves.',translation:'Trabajé en una tienda de comestibles, así que puedo revisar fechas y organizar estantes.'},{speaker:1,text:'That experience will be useful. We begin at eight and finish around noon.',translation:'Esa experiencia será útil. Empezamos a las ocho y terminamos cerca del mediodía.'},{speaker:0,text:'Should I bring anything or complete a form first?',translation:'¿Debo llevar algo o completar un formulario antes?'},{speaker:1,text:'Wear comfortable shoes. I will email you the registration form this evening.',translation:'Usa zapatos cómodos. Te enviaré el formulario de inscripción esta tarde.'}] },
  { id:27, level:'B1', title:'A Memorable Train Journey', titleEs:'Un viaje en tren memorable', summaryEs:'Dos amigos cuentan qué hizo especial un viaje reciente.', names:['Sofia (Friend)','Daniel (Friend)'], roles:['student','friend'], turns:[
    {speaker:0,text:'How was your trip to the coast last weekend?',translation:'¿Cómo estuvo tu viaje a la costa el fin de semana pasado?'},{speaker:1,text:'The train was delayed, but I met an older artist at the station.',translation:'El tren se retrasó, pero conocí a una artista mayor en la estación.'},{speaker:0,text:'What did you talk about while you were waiting?',translation:'¿De qué hablaron mientras esperaban?'},{speaker:1,text:'She told me how the harbor had changed since she was a child.',translation:'Me contó cómo había cambiado el puerto desde que era niña.'},{speaker:0,text:'Did you see her again after the train arrived?',translation:'¿Volviste a verla después de que llegó el tren?'},{speaker:1,text:'Yes. She showed me her paintings at a small gallery near the beach.',translation:'Sí. Me mostró sus pinturas en una pequeña galería cerca de la playa.'}] },
  { id:28, level:'B1', title:'Setting a Monthly Budget', titleEs:'Organizar un presupuesto mensual', summaryEs:'Dos compañeros revisan gastos y fijan una meta de ahorro.', names:['Julia (Friend)','Omar (Friend)'], roles:['student','friend'], turns:[
    {speaker:0,text:'I keep spending more than I planned each month. How do you manage your money?',translation:'Sigo gastando más de lo planeado cada mes. ¿Cómo administras tu dinero?'},{speaker:1,text:'I write down regular expenses first, then set a limit for eating out.',translation:'Primero anoto mis gastos fijos y después pongo un límite para comer fuera.'},{speaker:0,text:'I spend a lot on coffee because I buy it on my way to work.',translation:'Gasto mucho en café porque lo compro de camino al trabajo.'},{speaker:1,text:'You could make coffee at home a few days a week and save the difference.',translation:'Podrías preparar café en casa algunos días y ahorrar la diferencia.'},{speaker:0,text:'I will try that and transfer the savings into a separate account.',translation:'Lo intentaré y transferiré lo ahorrado a otra cuenta.'},{speaker:1,text:'That is practical. Review your budget again at the end of the month.',translation:'Es práctico. Revisa tu presupuesto de nuevo al final del mes.'}] },
  { id:29, level:'B1', title:'Giving Feedback After a Meeting', titleEs:'Dar comentarios después de una reunión', summaryEs:'Una colega ofrece comentarios constructivos sobre una presentación.', names:['Ravi (Colleague)','Emma (Colleague)'], roles:['student','colleague'], turns:[
    {speaker:0,text:'Could I give you some feedback on the presentation?',translation:'¿Puedo darte algunos comentarios sobre la presentación?'},{speaker:1,text:'Of course. What did you think?',translation:'Claro. ¿Qué te pareció?'},{speaker:0,text:'Your examples were clear, and the audience followed the main point.',translation:'Tus ejemplos fueron claros y el público siguió la idea principal.'},{speaker:1,text:'Thank you. Was anything difficult to understand?',translation:'Gracias. ¿Hubo algo difícil de entender?'},{speaker:0,text:'The final chart moved quickly. It might help to explain the numbers before showing it.',translation:'La gráfica final pasó rápido. Tal vez ayudaría explicar los números antes de mostrarla.'},{speaker:1,text:'That is useful. I will add a short explanation next time.',translation:'Es útil. Añadiré una breve explicación la próxima vez.'}] },
  { id:30, level:'B1', title:'Correcting a Restaurant Order', titleEs:'Corregir un pedido en un restaurante', summaryEs:'Un cliente aclara un pedido equivocado con cortesía.', names:['Nico (Customer)','Amelia (Server)'], roles:['customer','server'], turns:[
    {speaker:0,text:'Excuse me. I ordered the vegetable pasta, but this dish has chicken.',translation:'Disculpe. Pedí la pasta de verduras, pero este platillo tiene pollo.'},{speaker:1,text:'I am very sorry. I may have read the ticket incorrectly.',translation:'Lo siento mucho. Quizá leí mal la comanda.'},{speaker:0,text:'No problem. Could you check whether the kitchen can prepare the correct dish?',translation:'No hay problema. ¿Podría revisar si la cocina puede preparar el platillo correcto?'},{speaker:1,text:'Certainly. It will take about ten minutes. Would you like some bread meanwhile?',translation:'Por supuesto. Tardará unos diez minutos. ¿Quiere pan mientras tanto?'},{speaker:0,text:'That would be nice, thank you.',translation:'Eso estaría bien, gracias.'},{speaker:1,text:'I will bring it right away and make sure the new order is correct.',translation:'Lo traeré enseguida y me aseguraré de que el nuevo pedido esté correcto.'}] },
  { id:31, level:'B2', title:'Negotiating a Flexible Schedule', titleEs:'Negociar un horario flexible', summaryEs:'Una empleada propone un horario remoto que cubra al equipo.', names:['Priya (Designer)','Mr. Adams (Manager)'], roles:['student','manager'], turns:[
    {speaker:0,text:'I would like to discuss working remotely two days a week. My commute has become difficult.',translation:'Me gustaría hablar sobre trabajar desde casa dos días por semana. Mi traslado se ha vuelto complicado.'},{speaker:1,text:'How would you ensure the team can still reach you during core hours?',translation:'¿Cómo garantizarías que el equipo pueda localizarte durante el horario central?'},{speaker:0,text:'I can remain online from nine to four and join our scheduled reviews by video.',translation:'Puedo estar conectada de nueve a cuatro y participar por video en nuestras revisiones programadas.'},{speaker:1,text:'That could work, although client meetings sometimes change at short notice.',translation:'Podría funcionar, aunque las reuniones con clientes a veces cambian con poca antelación.'},{speaker:0,text:'I would come in on those days if needed, provided I receive reasonable notice.',translation:'Vendría a la oficina esos días si fuera necesario, siempre que reciba aviso razonable.'},{speaker:1,text:'Let us trial it for a month and review response times and project delivery.',translation:'Probémoslo durante un mes y revisemos los tiempos de respuesta y la entrega de proyectos.'}] },
  { id:32, level:'B2', title:'Explaining an AI Recommendation', titleEs:'Explicar una recomendación de IA', summaryEs:'Una especialista distingue una predicción automática de una decisión humana.', names:['Leah (Engineer)','Carlos (Reporter)'], roles:['student','journalist'], turns:[
    {speaker:0,text:'The system recommends articles based on reading patterns, but it does not understand them as a person would.',translation:'El sistema recomienda artículos según patrones de lectura, pero no los entiende como lo haría una persona.'},{speaker:1,text:'So when it suggests a story, is that a judgment about its quality?',translation:'Entonces, cuando sugiere una nota, ¿está juzgando su calidad?'},{speaker:0,text:'Not necessarily. It estimates what someone may click, which is only a proxy for usefulness.',translation:'No necesariamente. Estima qué podría recibir un clic, lo cual es solo un indicador indirecto de utilidad.'},{speaker:1,text:'Could that encourage sensational headlines?',translation:'¿Eso podría fomentar titulares sensacionalistas?'},{speaker:0,text:'It might, unless the goals and outcomes are reviewed carefully.',translation:'Podría, a menos que se revisen cuidadosamente los objetivos y resultados.'},{speaker:1,text:'I will make that distinction clear in the article.',translation:'Dejaré clara esa distinción en el artículo.'}] },
  { id:33, level:'B2', title:'Debating a Car-Free Street', titleEs:'Debatir una calle sin automóviles', summaryEs:'Dos residentes comparan accesibilidad, comercio y contaminación.', names:['Marta (Resident)','Jonah (Shop Owner)'], roles:['student','shop owner'], turns:[
    {speaker:0,text:'The city is considering closing this street to cars on weekends. I think it would make the area safer.',translation:'La ciudad considera cerrar esta calle a los autos los fines de semana. Creo que la haría más segura.'},{speaker:1,text:'I support cleaner air, but some customers rely on nearby parking.',translation:'Apoyo un aire más limpio, pero algunos clientes dependen del estacionamiento cercano.'},{speaker:0,text:'Could delivery access remain available before ten in the morning?',translation:'¿Podría mantenerse el acceso para entregas antes de las diez de la mañana?'},{speaker:1,text:'That would help. We should also measure whether foot traffic actually increases.',translation:'Eso ayudaría. También deberíamos medir si realmente aumenta el tránsito peatonal.'},{speaker:0,text:'Agreed. A three-month trial could reveal who benefits and who needs support.',translation:'De acuerdo. Una prueba de tres meses podría mostrar quién se beneficia y quién necesita apoyo.'},{speaker:1,text:'If the city publishes the results, I would be willing to reconsider.',translation:'Si la ciudad publica los resultados, estaría dispuesto a reconsiderarlo.'}] },
  { id:34, level:'B2', title:'Choosing a Book for the Club', titleEs:'Elegir un libro para el club', summaryEs:'Un club de lectura busca una novela que ofrezca distintas perspectivas.', names:['Nina (Organizer)','Theo (Member)'], roles:['student','member'], turns:[
    {speaker:0,text:'We need a novel for next month that will give everyone something to discuss.',translation:'Necesitamos una novela para el próximo mes que dé a todos algo que debatir.'},{speaker:1,text:'What about the historical novel you mentioned? Its narrator may be unreliable.',translation:'¿Qué tal la novela histórica que mencionaste? Puede que su narrador no sea fiable.'},{speaker:0,text:'That could lead to an interesting conversation, although the language is quite demanding.',translation:'Eso podría dar lugar a una conversación interesante, aunque el lenguaje es bastante exigente.'},{speaker:1,text:'We could share a short glossary before the meeting.',translation:'Podríamos compartir un glosario breve antes de la reunión.'},{speaker:0,text:'Good idea. I will send two options and let members vote.',translation:'Buena idea. Enviaré dos opciones y dejaré que los miembros voten.'},{speaker:1,text:'Then everyone has a say, and we can plan questions around the winning book.',translation:'Así todos pueden opinar y podremos preparar preguntas sobre el libro ganador.'}] },
  { id:35, level:'B2', title:'Presenting a Community Project', titleEs:'Presentar un proyecto comunitario', summaryEs:'Un equipo revisa cómo presentar evidencia y costos a los vecinos.', names:['Amir (Presenter)','Grace (Teammate)'], roles:['student','colleague'], turns:[
    {speaker:0,text:'The survey shows that residents want more shade, but only forty percent responded.',translation:'La encuesta muestra que los vecinos quieren más sombra, pero solo respondió el cuarenta por ciento.'},{speaker:1,text:'We should mention the response rate so we do not overstate the result.',translation:'Deberíamos mencionar la tasa de respuesta para no exagerar el resultado.'},{speaker:0,text:'Agreed. I will explain that the findings are suggestive rather than conclusive.',translation:'De acuerdo. Explicaré que los hallazgos son indicativos y no concluyentes.'},{speaker:1,text:'Could you also show the maintenance cost over five years?',translation:'¿También podrías mostrar el costo de mantenimiento a cinco años?'},{speaker:0,text:'Yes. That will help compare the initial price with the long-term benefit.',translation:'Sí. Eso ayudará a comparar el precio inicial con el beneficio a largo plazo.'},{speaker:1,text:'The presentation will be more credible if we acknowledge the trade-offs.',translation:'La presentación será más creíble si reconocemos las ventajas y desventajas.'}] },
  { id:36, level:'B2', title:'A Difficult Performance Review', titleEs:'Una evaluación de desempeño difícil', summaryEs:'Una supervisora aborda retrasos sin ignorar los logros del equipo.', names:['Helen (Supervisor)','Marcus (Designer)'], roles:['manager','student'], turns:[
    {speaker:0,text:'Your designs have been strong, but the last two submissions arrived after the agreed dates.',translation:'Tus diseños han sido sólidos, pero las dos últimas entregas llegaron después de las fechas acordadas.'},{speaker:1,text:'I understand. The client changed the requirements midway, and I did not raise the risk early enough.',translation:'Lo entiendo. El cliente cambió los requisitos a mitad del proceso y no señalé el riesgo con suficiente anticipación.'},{speaker:0,text:'That context matters. What could prevent a similar delay next time?',translation:'Ese contexto importa. ¿Qué podría prevenir un retraso similar la próxima vez?'},{speaker:1,text:'I could send a brief status note as soon as the scope changes.',translation:'Podría enviar una nota breve de estado en cuanto cambie el alcance.'},{speaker:0,text:'Let us agree on a checkpoint before the final deadline.',translation:'Acordemos un punto de revisión antes de la fecha final.'},{speaker:1,text:'That would help. I appreciate that we are focusing on a solution.',translation:'Eso ayudaría. Aprecio que nos estemos enfocando en una solución.'}] },
  { id:37, level:'B2', title:'Filing a Travel Insurance Claim', titleEs:'Presentar una reclamación de seguro de viaje', summaryEs:'Una viajera reúne evidencia tras la pérdida de su equipaje.', names:['Dina (Traveler)','Mr. White (Agent)'], roles:['customer','assistant'], turns:[
    {speaker:0,text:'My suitcase did not arrive, and I have already filed a report with the airline.',translation:'Mi maleta no llegó y ya presenté un reporte con la aerolínea.'},{speaker:1,text:'I am sorry to hear that. Please send us the report number and your boarding pass.',translation:'Lamento lo ocurrido. Envíenos el número del reporte y su pase de abordar.'},{speaker:0,text:'I also bought basic clothes and toiletries while I waited. Are those expenses covered?',translation:'También compré ropa básica y artículos de aseo mientras esperaba. ¿Esos gastos están cubiertos?'},{speaker:1,text:'They may be, up to your policy limit, if you provide itemized receipts.',translation:'Podrían estarlo, hasta el límite de su póliza, si presenta recibos detallados.'},{speaker:0,text:'I have the receipts on my phone. How long does a review usually take?',translation:'Tengo los recibos en mi teléfono. ¿Cuánto suele tardar la revisión?'},{speaker:1,text:'Once we receive all the documents, we aim to respond within ten business days.',translation:'Cuando recibamos todos los documentos, procuramos responder en diez días hábiles.'}] },
  { id:38, level:'B2', title:'Considering a Career Change', titleEs:'Considerar un cambio de carrera', summaryEs:'Una profesional sopesa seguridad laboral y un nuevo interés.', names:['Yuki (Analyst)','Sam (Friend)'], roles:['student','friend'], turns:[
    {speaker:0,text:'I have been thinking about leaving finance to train as a nurse.',translation:'He estado pensando en dejar las finanzas para formarme como enfermera.'},{speaker:1,text:'What appeals to you about nursing, and what concerns you?',translation:'¿Qué te atrae de la enfermería y qué te preocupa?'},{speaker:0,text:'I want more direct contact with people, but I would need to study for several years.',translation:'Quiero tener contacto más directo con la gente, pero tendría que estudiar varios años.'},{speaker:1,text:'Could you speak with nurses or volunteer at a clinic before deciding?',translation:'¿Podrías hablar con enfermeras o ser voluntaria en una clínica antes de decidir?'},{speaker:0,text:'That would give me a better sense of the daily work.',translation:'Eso me daría una mejor idea del trabajo diario.'},{speaker:1,text:'Exactly. You can explore the change without resigning immediately.',translation:'Exacto. Puedes explorar el cambio sin renunciar de inmediato.'}] },
  { id:39, level:'B2', title:'Reducing Household Waste', titleEs:'Reducir los residuos del hogar', summaryEs:'Una pareja elige cambios prácticos para reducir basura.', names:['Ava (Neighbor)','Luis (Neighbor)'], roles:['student','neighbor'], turns:[
    {speaker:0,text:'Our building is trying to reduce waste. What changes have worked for you?',translation:'Nuestro edificio intenta reducir residuos. ¿Qué cambios les han funcionado?'},{speaker:1,text:'We plan meals before shopping and use the same containers for leftovers.',translation:'Planeamos las comidas antes de comprar y usamos los mismos recipientes para las sobras.'},{speaker:0,text:'Do you think recycling alone makes a significant difference?',translation:'¿Crees que reciclar por sí solo hace una diferencia importante?'},{speaker:1,text:'It helps, but buying fewer disposable items has reduced our waste more.',translation:'Ayuda, pero comprar menos artículos desechables ha reducido más nuestra basura.'},{speaker:0,text:'We could start by replacing bottled water with a refillable filter.',translation:'Podríamos empezar cambiando el agua embotellada por un filtro rellenable.'},{speaker:1,text:'That is manageable. Small habits are more likely to last.',translation:'Eso es manejable. Es más probable que los hábitos pequeños perduren.'}] },
  { id:40, level:'B2', title:'Resolving a Billing Dispute', titleEs:'Resolver una disputa de facturación', summaryEs:'Un cliente y una asesora revisan un cobro duplicado.', names:['Renee (Customer)','Mr. Patel (Billing Agent)'], roles:['customer','assistant'], turns:[
    {speaker:0,text:'My statement shows the same subscription charge twice this month.',translation:'Mi estado de cuenta muestra dos veces el mismo cargo de suscripción este mes.'},{speaker:1,text:'I can investigate that. Could you confirm the dates and amounts?',translation:'Puedo investigarlo. ¿Podría confirmar las fechas y los importes?'},{speaker:0,text:'Both charges are for twelve dollars, one on the third and one on the fourth.',translation:'Ambos cargos son de doce dólares, uno el día tres y otro el cuatro.'},{speaker:1,text:'I see the duplicate. I will submit a refund request and email you a reference number.',translation:'Veo el duplicado. Enviaré una solicitud de reembolso y le mandaré un número de referencia.'},{speaker:0,text:'When should the credit appear?',translation:'¿Cuándo debería aparecer el abono?'},{speaker:1,text:'It usually takes five business days, depending on your bank.',translation:'Normalmente tarda cinco días hábiles, según su banco.'}] },
  { id:41, level:'C1', title:'Revising a Climate Adaptation Plan', titleEs:'Revisar un plan de adaptación climática', summaryEs:'Una urbanista y una funcionaria discuten prioridades y evidencia.', names:['Dr. Chen (Urban Planner)','Ms. Ortiz (City Official)'], roles:['student','manager'], turns:[
    {speaker:0,text:'The draft prioritizes neighborhoods with the highest average temperatures, but that may overlook residents exposed overnight.',translation:'El borrador prioriza los barrios con las temperaturas medias más altas, pero podría pasar por alto a quienes están expuestos durante la noche.'},{speaker:1,text:'Would time-of-day measurements change the ranking substantially?',translation:'¿Las mediciones por hora cambiarían sustancialmente el orden de prioridad?'},{speaker:0,text:'In two districts, they would. Nighttime heat remains high even where the daytime average appears moderate.',translation:'En dos distritos, sí. El calor nocturno sigue siendo alto incluso donde el promedio diurno parece moderado.'},{speaker:1,text:'Then the report should distinguish those risks instead of collapsing them into one score.',translation:'Entonces el informe debería distinguir esos riesgos en vez de reducirlos a una sola puntuación.'},{speaker:0,text:'Agreed. I will include the underlying measures and explain why the revised map differs.',translation:'De acuerdo. Incluiré las mediciones de base y explicaré por qué difiere el mapa revisado.'},{speaker:1,text:'That may complicate the summary, but it makes the decision more defensible.',translation:'Eso quizá complique el resumen, pero hace que la decisión sea más defendible.'}] },
  { id:42, level:'C1', title:'Interpreting Preliminary Research', titleEs:'Interpretar una investigación preliminar', summaryEs:'Una editora pide precisión al describir un estudio pequeño.', names:['Mina (Editor)','Dr. Lewis (Researcher)'], roles:['editor','student'], turns:[
    {speaker:0,text:'The release says the intervention prevents memory loss. Does the study support that wording?',translation:'El comunicado dice que la intervención previene la pérdida de memoria. ¿El estudio respalda esa formulación?'},{speaker:1,text:'It found improved scores on one task after six weeks, but the sample was small.',translation:'Encontró mejores puntuaciones en una tarea tras seis semanas, pero la muestra era pequeña.'},{speaker:0,text:'Then “prevents memory loss” implies a broader and more durable effect than you measured.',translation:'Entonces “previene la pérdida de memoria” implica un efecto más amplio y duradero del que midieron.'},{speaker:1,text:'That is fair. We should say the results may indicate a short-term improvement on that task.',translation:'Es razonable. Deberíamos decir que los resultados podrían indicar una mejora a corto plazo en esa tarea.'},{speaker:0,text:'Could you also note that further research is needed?',translation:'¿Podría añadir también que se necesita más investigación?'},{speaker:1,text:'Yes. I would rather qualify the claim than create expectations the evidence cannot meet.',translation:'Sí. Preferiría matizar la afirmación antes que crear expectativas que la evidencia no puede satisfacer.'}] },
  { id:43, level:'C1', title:'Discussing the Return of an Artifact', titleEs:'Debatir la devolución de un objeto cultural', summaryEs:'Una conservadora y una representante comunitaria analizan opciones de restitución.', names:['Dr. Shah (Curator)','Nia (Community Representative)'], roles:['curator','student'], turns:[
    {speaker:0,text:'Our records document the artifact’s arrival, but they do not establish that its removal was consensual.',translation:'Nuestros registros documentan la llegada del objeto, pero no establecen que su traslado haya sido consentido.'},{speaker:1,text:'The absence of a record cannot reasonably be treated as evidence that our community agreed.',translation:'Razonablemente, la ausencia de un registro no puede tomarse como prueba de que nuestra comunidad estuvo de acuerdo.'},{speaker:0,text:'I accept that. The museum has discussed a long-term loan as an interim measure.',translation:'Lo acepto. El museo ha considerado un préstamo a largo plazo como medida provisional.'},{speaker:1,text:'A loan still leaves ownership and the terms of access with the museum.',translation:'Un préstamo aún deja la propiedad y las condiciones de acceso en manos del museo.'},{speaker:0,text:'You are right. We should compare that option with shared stewardship and return.',translation:'Tiene razón. Deberíamos comparar esa opción con la gestión compartida y la devolución.'},{speaker:1,text:'A transparent process would help, provided our representatives can shape the decision rather than merely advise.',translation:'Un proceso transparente ayudaría, siempre que nuestros representantes puedan influir en la decisión y no solo asesorar.'}] },
  { id:44, level:'C1', title:'Setting Rules for AI in Schools', titleEs:'Establecer reglas para la IA en las escuelas', summaryEs:'Una directora y un docente debaten usos aceptables de IA.', names:['Dr. Evans (Principal)','Mr. Rivera (Teacher)'], roles:['manager','teacher'], turns:[
    {speaker:0,text:'The board wants one rule for all uses of generative AI. Would a blanket ban be workable?',translation:'La junta quiere una sola regla para todos los usos de la IA generativa. ¿Sería viable una prohibición general?'},{speaker:1,text:'It would be simple to communicate, but it could prevent useful accessibility and feedback tools.',translation:'Sería fácil de comunicar, pero podría impedir herramientas útiles de accesibilidad y retroalimentación.'},{speaker:0,text:'How could we distinguish support from submitting machine-written work as one’s own?',translation:'¿Cómo podríamos distinguir el apoyo de presentar como propio un trabajo escrito por una máquina?'},{speaker:1,text:'Require disclosure and assess drafts, sources, and the student’s explanation of their reasoning.',translation:'Exijamos que se declare su uso y evaluemos borradores, fuentes y la explicación del razonamiento del estudiante.'},{speaker:0,text:'That places more responsibility on teachers and may not be perfectly consistent.',translation:'Eso asigna más responsabilidad al profesorado y quizá no sea del todo uniforme.'},{speaker:1,text:'True, but a contextual policy is more defensible than treating every tool use as misconduct.',translation:'Es cierto, pero una política contextual es más defendible que tratar todo uso de herramientas como falta.'}] },
  { id:45, level:'C1', title:'A Conversation About Burnout', titleEs:'Una conversación sobre agotamiento laboral', summaryEs:'Una mentora escucha a un colega y acuerdan cambios sostenibles.', names:['Helen (Mentor)','Ravi (Colleague)'], roles:['manager','colleague'], turns:[
    {speaker:0,text:'You have seemed unusually withdrawn. Is the workload becoming unsustainable?',translation:'Te he notado inusualmente distante. ¿La carga de trabajo se está volviendo insostenible?'},{speaker:1,text:'I can meet the deadlines, but only by working late most evenings. That is beginning to affect my health.',translation:'Puedo cumplir los plazos, pero solo trabajando hasta tarde casi todas las noches. Eso empieza a afectar mi salud.'},{speaker:0,text:'Meeting targets should not depend on a pattern that cannot be maintained.',translation:'Cumplir los objetivos no debería depender de un patrón que no pueda sostenerse.'},{speaker:1,text:'I have hesitated to raise it because I do not want to seem unreliable.',translation:'He dudado en plantearlo porque no quiero parecer poco fiable.'},{speaker:0,text:'Flagging a capacity issue early is responsible. Let us review priorities with the team lead.',translation:'Señalar pronto un problema de capacidad es responsable. Revisemos las prioridades con la jefa del equipo.'},{speaker:1,text:'I would appreciate that. I can propose what should be delayed rather than just saying no.',translation:'Lo agradecería. Puedo proponer qué debería aplazarse en vez de simplemente decir que no.'}] },
  { id:46, level:'C1', title:'Planning a Public Space', titleEs:'Planificar un espacio público', summaryEs:'Residentes y arquitectos buscan equilibrar acceso, ruido y actividades.', names:['Amara (Architect)','Felix (Resident)'], roles:['architect','student'], turns:[
    {speaker:0,text:'The proposal adds an event stage, although nearby residents have raised concerns about evening noise.',translation:'La propuesta añade un escenario, aunque los residentes cercanos han expresado preocupación por el ruido nocturno.'},{speaker:1,text:'The space is underused now, but frequent events could exclude people who need a quiet place.',translation:'El espacio casi no se usa ahora, pero los eventos frecuentes podrían excluir a quienes necesitan un lugar tranquilo.'},{speaker:0,text:'Would limiting events to two weekends a month address part of that concern?',translation:'¿Limitar los eventos a dos fines de semana al mes atendería parte de esa inquietud?'},{speaker:1,text:'It would, provided the schedule is published and residents can comment before it is finalized.',translation:'Sí, siempre que se publique el calendario y los residentes puedan opinar antes de que se cierre.'},{speaker:0,text:'We can also retain the garden area and improve lighting along the walking route.',translation:'También podemos conservar el área de jardín y mejorar la iluminación del sendero.'},{speaker:1,text:'That combination seems more inclusive than judging the plan by attendance alone.',translation:'Esa combinación parece más inclusiva que juzgar el plan solo por la asistencia.'}] },
  { id:47, level:'C1', title:'Editing a Breaking-News Headline', titleEs:'Editar un titular de última hora', summaryEs:'Una reportera y un editor separan hechos confirmados de rumores.', names:['Maya (Reporter)','Jon (Editor)'], roles:['student','editor'], turns:[
    {speaker:0,text:'Several posts claim the bridge has collapsed, but our source confirms only that it is closed.',translation:'Varias publicaciones afirman que el puente se derrumbó, pero nuestra fuente solo confirma que está cerrado.'},{speaker:1,text:'Then the headline must not repeat the unverified claim, even with a question mark.',translation:'Entonces el titular no debe repetir la afirmación no verificada, ni siquiera con signos de interrogación.'},{speaker:0,text:'Could we say that authorities closed the bridge while engineers inspect a possible structural issue?',translation:'¿Podemos decir que las autoridades cerraron el puente mientras los ingenieros inspeccionan un posible problema estructural?'},{speaker:1,text:'Yes, if both details are confirmed and we attribute the inspection to the authorities.',translation:'Sí, si ambos detalles están confirmados y atribuimos la inspección a las autoridades.'},{speaker:0,text:'I will contact the city again before filing the update.',translation:'Volveré a contactar a la ciudad antes de enviar la actualización.'},{speaker:1,text:'Good. Accuracy may cost us a few minutes, but speculation could cost readers’ trust.',translation:'Bien. La precisión puede costarnos unos minutos, pero la especulación podría costarnos la confianza de los lectores.'}] },
  { id:48, level:'C1', title:'Preserving Regional Language', titleEs:'Preservar una lengua regional', summaryEs:'Dos lingüistas discuten cómo documentar variantes sin jerarquizarlas.', names:['Professor Allen (Linguist)','Lucia (Community Researcher)'], roles:['teacher','student'], turns:[
    {speaker:0,text:'The school requested one standardized spelling system for its new materials.',translation:'La escuela pidió un único sistema ortográfico estandarizado para sus nuevos materiales.'},{speaker:1,text:'A standard may aid beginners, yet it could imply that neighboring varieties are incorrect.',translation:'Un estándar podría ayudar a principiantes, pero podría insinuar que las variantes vecinas son incorrectas.'},{speaker:0,text:'How might we support consistent instruction without erasing those differences?',translation:'¿Cómo podríamos apoyar una enseñanza coherente sin borrar esas diferencias?'},{speaker:1,text:'Teach a common written form while recording local speakers and noting where each variant is used.',translation:'Enseñemos una forma escrita común mientras grabamos a hablantes locales y anotamos dónde se usa cada variante.'},{speaker:0,text:'That would make the materials more complex, but arguably more accurate.',translation:'Eso haría los materiales más complejos, pero posiblemente más precisos.'},{speaker:1,text:'And it signals that variation is part of the language, not a flaw to be corrected.',translation:'Y señala que la variación es parte de la lengua, no un defecto que deba corregirse.'}] },
  { id:49, level:'C1', title:'Allocating Adaptation Funding', titleEs:'Asignar fondos para adaptación', summaryEs:'Una analista y una funcionaria debaten criterios para distribuir recursos.', names:['Dr. Okafor (Analyst)','Ms. Vega (Director)'], roles:['student','manager'], turns:[
    {speaker:0,text:'The current formula directs funds to places with the largest recorded losses, which may favor areas with better reporting systems.',translation:'La fórmula actual dirige fondos a lugares con las mayores pérdidas registradas, lo que podría favorecer zonas con mejores sistemas de reporte.'},{speaker:1,text:'We still need comparable evidence. What alternative would be transparent?',translation:'Aun así necesitamos evidencia comparable. ¿Qué alternativa sería transparente?'},{speaker:0,text:'Combine verified losses with exposure and capacity indicators, then publish how each factor is weighted.',translation:'Combinemos pérdidas verificadas con indicadores de exposición y capacidad, y publiquemos la ponderación de cada factor.'},{speaker:1,text:'A composite measure could conceal value judgments behind a single number.',translation:'Una medida compuesta podría ocultar juicios de valor detrás de un único número.'},{speaker:0,text:'Then we should show the component scores and invite an independent review.',translation:'Entonces deberíamos mostrar las puntuaciones de cada componente e invitar a una revisión independiente.'},{speaker:1,text:'That would not eliminate disagreement, but it would make the trade-offs visible.',translation:'Eso no eliminaría el desacuerdo, pero haría visibles las ventajas y desventajas.'}] },
  { id:50, level:'C1', title:'Reflecting on Leadership', titleEs:'Reflexionar sobre el liderazgo', summaryEs:'Una directora explica cómo cambió su manera de tomar decisiones.', names:['Nora (Director)','Eli (New Manager)'], roles:['manager','student'], turns:[
    {speaker:0,text:'I used to think a leader had to provide an answer immediately.',translation:'Antes pensaba que una líder debía ofrecer una respuesta de inmediato.'},{speaker:1,text:'What changed your perspective?',translation:'¿Qué cambió tu perspectiva?'},{speaker:0,text:'I made a decision quickly during a restructuring, and the team later uncovered information I had not considered.',translation:'Tomé una decisión rápida durante una reestructuración y después el equipo descubrió información que no había considerado.'},{speaker:1,text:'Did you reverse the decision?',translation:'¿Revertiste la decisión?'},{speaker:0,text:'Partly. More importantly, I began stating what remains uncertain and asking who has not been heard.',translation:'En parte. Y, más importante, empecé a señalar qué sigue siendo incierto y a preguntar quién no ha sido escuchado.'},{speaker:1,text:'That sounds less decisive, but perhaps more accountable.',translation:'Suena menos decidido, pero quizá más responsable.'}] },
];

const durationByLevel: Record<DialogueSeed['level'], string> = {
  A1: '2–3 min', A2: '3–4 min', B1: '4–5 min', B2: '5–6 min', C1: '6–8 min',
};

export const additionalDialogues: Dialogue[] = seeds.map(seed => ({
  id: seed.id,
  title: seed.title,
  titleEs: seed.titleEs,
  level: seed.level,
  description: `${seed.level}-level English conversation for listening and role-play practice.`,
  descriptionEs: seed.summaryEs,
  duration: durationByLevel[seed.level],
  lines: seed.turns.map((turn, index): DialogueLine => ({
    id: index + 1,
    speaker: seed.roles[turn.speaker],
    speakerName: seed.names[turn.speaker],
    text: turn.text,
    translation: turn.translation,
  })),
}));
